1	// D2 写真を破る: 両手で持った写真を、片手は手前・もう片手は奥へ素早く逆向きに動かすと、左右 2 枚に破れて落ちて消える。
2	import * as THREE from 'three';
3	import type { FrameContext } from '../../app';
4	import type { HandState } from '../../input';
5	import type { Item } from '../../items';
6	import type { InteractionFactory } from '../types';
7	
8	/** 両手を結ぶ線に垂直な、互いに逆向きの相対速度がこれ以上 (m/s)。両手で拡大縮小・回転する普通の動きは 0.5 m/s 未満に収まるので、その倍以上の素早さを要求する。 */
9	export const TEAR_RELATIVE_SPEED = 0.8;
10	/** 破るとき、各手がそれぞれ出していなければならない垂直方向の速さ (m/s)。片手だけを振っても (もう片手がほぼ止まったままでも) 破れない。 */
11	export const TEAR_EACH_HAND_SPEED = 0.25;
12	/** 線に沿った相対速度 (拡大縮小) が、垂直な相対速度のこの割合を超えたら、引き伸ばしと見なして破らない。 */
13	export const TEAR_MAX_ALONG_RATIO = 0.5;
14	/** 上の条件を満たし続ける時間 (秒)。手の速度は 1 フレームだけ跳ねることがあるので、少し続いたときだけ破る。 */
15	export const TEAR_SUSTAIN = 0.05;
16	/** 片手のつまみが外れてから、直前まで両手で持っていた写真を破る対象に残す時間 (秒)。素手は速く動かすと握りが外れやすいため。 */
17	export const TEAR_GRACE = 0.15;
18	/** 手の速度を測り直す時間幅 (秒)。HandState.velocity は 0.1 秒の平均で、素早い動きが小さく出るので、この案では短い幅でも測り、大きい方を使う。 */
19	const SHORT_VELOCITY_WINDOW = 0.04;
20	/**
21	 * 回転との区別。垂直・逆向きの動きは、写真をゆっくり回すときにも出る。
22	 * 破る動きは一気に立ち上がるので、この速さ (m/s) 以上、破る閾値未満の動きが SLOW_RAMP_LIMIT 秒を超えて続いたら
23	 * 「回している」と見なし、動きがこの速さを下回るまで破らない。
24	 */
25	const SLOW_RAMP_SPEED = 0.3;
26	const SLOW_RAMP_LIMIT = 0.5;
27	/** 破れそうなとき、写真に入る裂け目の最大の長さ (写真の高さに対する割合) */
28	const CRACK_MAX_RATIO = 0.9;
29	/** 破れてから消えるまでの時間 (秒) */
30	const FALL_DURATION = 0.9;
31	/** 破片が左右へ離れる速さ (m/s、写真の大きさに対する倍率前) */
32	const SPREAD_SPEED = 0.18;
33	/** 破片が落ちる加速度 (m/s^2)。実際の重力より弱めにして、ひらひら落ちる見た目にする */
34	const FALL_GRAVITY = 3;
35	/** 破片が回る速さ (rad/s)。左右で逆向きに回す */
36	const SPIN_SPEED = 1.4;
37	
38	const _axis = new THREE.Vector3();
39	const _vl = new THREE.Vector3();
40	const _vr = new THREE.Vector3();
41	const _rel = new THREE.Vector3();
42	const _dir = new THREE.Vector3();
43	
44	export interface TearMetrics {
45	  /** 両手を結ぶ線に垂直な、相対速度の大きさ (m/s) */
46	  perp: number;
47	  /** 線に沿った相対速度の大きさ (m/s)。拡大縮小の速さ */
48	  along: number;
49	  /** 相対運動の向きに対して、右手は正方向・左手は負方向へ動いた速さのうち、小さい方。逆向きに動いていなければ負になる。 */
50	  eachMin: number;
51	}
52	
53	/** 両手を結ぶ線に垂直な、互いに逆向きの動きの量を測る (純粋な計算)。手が重なっていて線が決まらなければ null。 */
54	export function measureTear(
55	  leftPos: THREE.Vector3,
56	  rightPos: THREE.Vector3,
57	  leftVel: THREE.Vector3,
58	  rightVel: THREE.Vector3,
59	): TearMetrics | null {
60	  _axis.subVectors(rightPos, leftPos);
61	  if (_axis.lengthSq() < 1e-6) return null;
62	  _axis.normalize();
63	  // 各手の速度から、線に沿った成分を引いて垂直成分にする
64	  _vl.copy(leftVel).addScaledVector(_axis, -leftVel.dot(_axis));
65	  _vr.copy(rightVel).addScaledVector(_axis, -rightVel.dot(_axis));
66	  _rel.subVectors(_vr, _vl);
67	  const perp = _rel.length();
68	  const along = Math.abs(_dir.subVectors(rightVel, leftVel).dot(_axis));
69	  if (perp < 1e-6) return { perp, along, eachMin: 0 };
70	  _dir.copy(_rel).divideScalar(perp);
71	  return { perp, along, eachMin: Math.min(_vr.dot(_dir), -_vl.dot(_dir)) };
72	}
73	
74	/** 破る動きか。互いに逆向きで十分速く、線に沿った動き (拡大縮小) より支配的であること。 */
75	export function isTearingMotion(
76	  leftPos: THREE.Vector3,
77	  rightPos: THREE.Vector3,
78	  leftVel: THREE.Vector3,
79	  rightVel: THREE.Vector3,
80	): boolean {
81	  const m = measureTear(leftPos, rightPos, leftVel, rightVel);
82	  return !!m && m.perp >= TEAR_RELATIVE_SPEED && m.along <= m.perp * TEAR_MAX_ALONG_RATIO && m.eachMin >= TEAR_EACH_HAND_SPEED;
83	}
84	
85	/** 破れそうな度合い (0 ～ 1)。破る閾値に対する垂直・逆向きの速さの割合で、線に沿った動きが勝っているときは 0。 */
86	export function tearProgress(m: TearMetrics | null): number {
87	  if (!m || m.eachMin <= 0 || m.along > m.perp * TEAR_MAX_ALONG_RATIO) return 0;
88	  return Math.min(m.perp / TEAR_RELATIVE_SPEED, 1);
89	}
90	
91	/** 写真の半分 (左: -1 / 右: +1) の板。写真の中心を原点とするローカル座標のまま、UV もテクスチャの半分に合わせる。 */
92	function halfPlane(width: number, height: number, side: -1 | 1, uvStart: number, uvEnd: number): THREE.PlaneGeometry {
93	  const geometry = new THREE.PlaneGeometry(width / 2, height);
94	  geometry.translate((side * width) / 4, 0, 0);
95	  const uv = geometry.getAttribute('uv');
96	  for (let i = 0; i < uv.count; i++) {
97	    uv.setX(i, uvStart + uv.getX(i) * (uvEnd - uvStart));
98	  }
99	  return geometry;
100	}
101	
102	/** 破る判定の対象にしている写真と、それを両手で持っていた手 */
103	interface Candidate {
104	  item: Item;
105	  left: HandState;
106	  right: HandState;
107	  /** 最後に両手で持っていた時刻 */
108	  lastBoth: number;
109	  /** ゆっくりした垂直・逆向きの動きが続いている時間 */
110	  slowTime: number;
111	  /** 回していると見なして、破るのを止めている */
112	  locked: boolean;
113	}
114	
115	interface Fragment {
116	  group: THREE.Group;
117	  side: -1 | 1;
118	  age: number;
119	  /** 下向きの速さ (m/s、写真のローカルではなくワールド) */
120	  fall: number;
121	  materials: THREE.MeshBasicMaterial[];
122	  textures: THREE.Texture[];
123	}
124	
125	const create: InteractionFactory = (ctx) => {
126	  const fragments: Fragment[] = [];
127	  let sustained = 0;
128	  let clock = 0;
129	  let charge = 0;
130	  let pulseTimer = 0;
131	  let candidate: Candidate | null = null;
132	  const histories = new WeakMap<HandState, { time: number; position: THREE.Vector3 }[]>();
133	  let crack: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | null = null;
134	
135	  /** 手の速度。HandState.velocity (0.1 秒の平均) と、直近の短い幅で測り直した速度のうち、大きい方を使う。 */
136	  const _short = new THREE.Vector3();
137	  const fasterVelocity = (hand: HandState, time: number): THREE.Vector3 => {
138	    let history = histories.get(hand);
139	    if (!history) histories.set(hand, (history = []));
140	    history.push({ time, position: hand.grabPosition.clone() });
141	    while (history.length > 2 && time - history[0].time > SHORT_VELOCITY_WINDOW) history.shift();
142	    const elapsed = time - history[0].time;
143	    if (history.length < 2 || elapsed < 1e-4) return hand.velocity;
144	    _short.copy(hand.grabPosition).sub(history[0].position).divideScalar(elapsed);
145	    return _short.lengthSq() > hand.velocity.lengthSq() ? _short.clone() : hand.velocity;
146	  };
147	
148	  /** 写真の上端から下へ伸びる、破れかけの裂け目。progress が 0 なら隠す。 */
149	  const updateCrack = (photo: Item | null, progress: number): void => {
150	    if (!photo || progress < 0.05) {
151	      if (crack) crack.visible = false;
152	      return;
153	    }
154	    const picture = photo.object.children[1] as THREE.Mesh<THREE.PlaneGeometry> | undefined;
155	    if (!picture) return;
156	    if (!crack) {
157	      crack = new THREE.Mesh(
158	        new THREE.PlaneGeometry(0.006, 1),
159	        // 裂け目は「穴」にする。MR のパススルーは、フレームバッファの alpha が 0 の所に映るので、
160	        // 写真の上に色を載せる代わりに、描く先の色と alpha を 0 に上書きする (src と dst の係数をどちらも 0 にする)。
161	        // 写真のテクスチャは触らないので、破るのをやめて裂け目を隠せば、元の見た目にそのまま戻る。
162	        new THREE.MeshBasicMaterial({
163	          side: THREE.DoubleSide,
164	          transparent: true,
165	          depthWrite: false,
166	          blending: THREE.CustomBlending,
167	          blendEquation: THREE.AddEquation,
168	          blendSrc: THREE.ZeroFactor,
169	          blendDst: THREE.ZeroFactor,
170	          blendSrcAlpha: THREE.ZeroFactor,
171	          blendDstAlpha: THREE.ZeroFactor,
172	        }),
173	      );
174	      // 透明な物の中では、写真より後に描く
175	      crack.renderOrder = 10;
176	      ctx.app.scene.add(crack);
177	    }
178	    const scale = photo.object.scale.x;
179	    const length = picture.geometry.parameters.height * CRACK_MAX_RATIO * progress;
180	    crack.visible = true;
181	    crack.quaternion.copy(photo.object.quaternion);
182	    crack.scale.set(scale, length * scale, 1);
183	    // 写真ローカルで、上端から下へ length だけ伸ばす。写真の面から少し手前に浮かせる。
184	    crack.position
185	      .set(0, (picture.geometry.parameters.height - length) / 2, 0.004)
186	      .multiplyScalar(scale)
187	      .applyQuaternion(photo.object.quaternion)
188	      .add(photo.object.position);
189	  };
190	
191	  const dispose = (fragment: Fragment): void => {
192	    ctx.app.scene.remove(fragment.group);
193	    for (const child of fragment.group.children) (child as THREE.Mesh).geometry.dispose();
194	    for (const material of fragment.materials) material.dispose();
195	    for (const texture of fragment.textures) texture.dispose();
196	  };
197	
198	  /** 写真と同じ位置・向き・大きさに、左右 2 枚の破片を出す。元の写真は呼び出し側が消す。 */
199	  const spawnFragments = (photo: Item): void => {
200	    const group = photo.object;
201	    const mount = group.children[0] as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | undefined;
202	    const picture = group.children[1] as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial> | undefined;
203	    const map = picture?.material.map;
204	    if (!mount || !picture) return;
205	    const { width, height } = picture.geometry.parameters;
206	    const mountWidth = mount.geometry.parameters.width;
207	    const mountHeight = mount.geometry.parameters.height;
208	    for (const side of [-1, 1] as const) {
209	      const fragment = new THREE.Group();
210	      const texture = map?.clone() ?? null;
211	      if (texture) texture.needsUpdate = true;
212	      const pictureMaterial = new THREE.MeshBasicMaterial({
213	        map: texture,
214	        side: THREE.DoubleSide,
215	        transparent: true,
216	      });
217	      const mountMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, transparent: true });
218	      const mountMesh = new THREE.Mesh(halfPlane(mountWidth, mountHeight, side, 0, 1), mountMaterial);
219	      mountMesh.position.z = mount.position.z;
220	      const pictureMesh = new THREE.Mesh(
221	        halfPlane(width, height, side, side < 0 ? 0 : 0.5, side < 0 ? 0.5 : 1),
222	        pictureMaterial,
223	      );
224	      fragment.add(mountMesh, pictureMesh);
225	      fragment.position.copy(group.position);
226	      fragment.quaternion.copy(group.quaternion);
227	      fragment.scale.copy(group.scale);
228	      ctx.app.scene.add(fragment);
229	      fragments.push({
230	        group: fragment,
231	        side,
232	        age: 0,
233	        fall: 0,
234	        materials: [pictureMaterial, mountMaterial],
235	        textures: texture ? [texture] : [],
236	      });
237	    }
238	  };
239	
240	  const tear = (photo: Item, hands: HandState[]): void => {
241	    const position = photo.object.position.clone();
242	    spawnFragments(photo);
243	    // 破る音は既存の音で代用する。紙を裂くような短い音を 2 つ、少しずらして鳴らす。
244	    ctx.audio.click(position);
245	    setTimeout(() => ctx.audio.click(position), 60);
246	    for (const hand of hands) hand.pulse(0.9, 80);
247	    ctx.items.remove(photo);
248	  };
249	
250	  return {
251	    id: 'D2',
252	    label: '破る',
253	    category: 'delete',
254	    disable() {
255	      for (const fragment of fragments) dispose(fragment);
256	      fragments.length = 0;
257	      sustained = 0;
258	      charge = 0;
259	      candidate = null;
260	      if (crack) {
261	        ctx.app.scene.remove(crack);
262	        crack.geometry.dispose();
263	        crack.material.dispose();
264	        crack = null;
265	      }
266	    },
267	    update(frame: FrameContext) {
268	      // 破片のアニメーション
269	      for (let i = fragments.length - 1; i >= 0; i--) {
270	        const fragment = fragments[i];
271	        fragment.age += frame.dt;
272	        const t = fragment.age / FALL_DURATION;
273	        if (t >= 1) {
274	          dispose(fragment);
275	          fragments.splice(i, 1);
276	          continue;
277	        }
278	        const scale = fragment.group.scale.x;
279	        // 写真のローカル x 方向 (写真の横向き) へ離れる
280	        _dir.set(fragment.side, 0, 0).applyQuaternion(fragment.group.quaternion);
281	        fragment.fall += FALL_GRAVITY * frame.dt;
282	        fragment.group.position
283	          .addScaledVector(_dir, SPREAD_SPEED * scale * frame.dt)
284	          .addScaledVector(_dir.set(0, -1, 0), fragment.fall * frame.dt);
285	        fragment.group.rotateZ(-fragment.side * SPIN_SPEED * frame.dt);
286	        const opacity = 1 - t * t;
287	        for (const material of fragment.materials) material.opacity = opacity;
288	      }
289	
290	      clock += frame.dt;
291	      // 両手で持った写真を、破る判定の対象にする。片手が外れても TEAR_GRACE の間は、直前まで持っていた写真を残す。
292	      const held = ctx.items.all.find((item) => item.kind === 'photo' && ctx.items.holdersOf(item).length === 2);
293	      if (held) {
294	        const hands = ctx.items.holdersOf(held);
295	        const left = hands.find((hand) => hand.handedness === 'left');
296	        const right = hands.find((hand) => hand.handedness === 'right');
297	        if (left && right) {
298	          if (candidate?.item !== held) {
299	            candidate = { item: held, left, right, lastBoth: clock, slowTime: 0, locked: false };
300	            sustained = 0;
301	          }
302	          candidate.left = left;
303	          candidate.right = right;
304	          candidate.lastBoth = clock;
305	        }
306	      }
307	      if (candidate && (!ctx.items.all.includes(candidate.item) || clock - candidate.lastBoth > TEAR_GRACE)) {
308	        candidate = null;
309	      }
310	      if (!candidate) {
311	        sustained = 0;
312	        charge = 0;
313	        updateCrack(null, 0);
314	        return;
315	      }
316	      const { item: photo, left, right } = candidate;
317	      if (!left.tracked || !right.tracked) {
318	        sustained = 0;
319	        return;
320	      }
321	      const lv = fasterVelocity(left, clock);
322	      const rv = fasterVelocity(right, clock);
323	      const metrics = measureTear(left.grabPosition, right.grabPosition, lv, rv);
324	
325	      // ゆっくり回しているだけのときは破らない
326	      const perp = metrics && metrics.eachMin > 0 ? metrics.perp : 0;
327	      if (perp < SLOW_RAMP_SPEED) {
328	        candidate.slowTime = 0;
329	        candidate.locked = false;
330	      } else if (perp < TEAR_RELATIVE_SPEED) {
331	        candidate.slowTime += frame.dt;
332	        if (candidate.slowTime > SLOW_RAMP_LIMIT) candidate.locked = true;
333	      }
334	
335	      // 破れそうな度合いを、裂け目で見せる (素手は振動が無いので、見た目が頼り)
336	      const target = candidate.locked ? 0 : tearProgress(metrics);
337	      charge += (target - charge) * Math.min(1, frame.dt * 15);
338	      updateCrack(photo, charge);
339	      pulseTimer -= frame.dt;
340	      if (charge > 0.5 && pulseTimer <= 0) {
341	        pulseTimer = 0.08;
342	        left.pulse(0.15 * charge, 30);
343	        right.pulse(0.15 * charge, 30);
344	      }
345	
346	      if (
347	        !candidate.locked &&
348	        isTearingMotion(left.grabPosition, right.grabPosition, lv, rv)
349	      ) {
350	        sustained += frame.dt;
351	        if (sustained >= TEAR_SUSTAIN) {
352	          sustained = 0;
353	          candidate = null;
354	          charge = 0;
355	          updateCrack(null, 0);
356	          tear(photo, [left, right]);
357	        }
358	      } else {
359	        sustained = 0;
360	      }
361	    },
362	  };
363	};
364	
365	export default create;
366

